package com.primehr.security;
import com.primehr.integration.administrative.*;import org.junit.jupiter.api.Test;import org.springframework.security.access.AccessDeniedException;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
class PerformanceCoachingPermissionGuardTest{
 @Test void coachingActionsAndScopesRemainIndependent(){var client=mock(AdministrativeAuthorizationClient.class);var guard=new PerformanceCoachingPermissionGuard(client);when(client.resolve(PerformanceCoachingPermissionGuard.FEATURE,"token")).thenReturn(permission(true,true,true,true,false,PermissionDataScope.ASSIGNED_RECORDS));assertThat(guard.require(PrimeHrAction.ADD,"token")).isEqualTo(PermissionDataScope.ASSIGNED_RECORDS);assertThat(guard.require(PrimeHrAction.SUBMIT,"token")).isEqualTo(PermissionDataScope.ASSIGNED_RECORDS);assertThatThrownBy(()->guard.require(PrimeHrAction.APPROVE,"token")).isInstanceOf(AccessDeniedException.class);when(client.resolve(PerformanceCoachingPermissionGuard.FEATURE,"token")).thenReturn(permission(true,true,true,true,true,PermissionDataScope.NONE));assertThatThrownBy(()->guard.require(PrimeHrAction.ACCESS,"token")).isInstanceOf(AccessDeniedException.class);}
 private static EffectiveFeaturePermission permission(boolean access,boolean add,boolean edit,boolean submit,boolean approve,PermissionDataScope scope){return new EffectiveFeaturePermission(PerformanceCoachingPermissionGuard.FEATURE,false,access,add,edit,false,false,submit,approve,false,false,false,scope);}
}
